use std::collections::BTreeMap;

use crate::amount::Amount;
use crate::catalog::{base_premium, insurance_value, is_component};
use crate::components::component_group_premium;

/// One insured item as described in a quote step.
#[derive(Debug, Clone)]
pub struct Item {
    pub item_type: String,
    pub material: Option<String>,
    pub enchantment: Option<i64>,
    pub cursed: bool,
}

/// An item type the MHPCO price list does not cover.
#[derive(Debug, PartialEq, Eq)]
pub struct UnknownItemType(pub String);

/// The items covered by one policy, validated against the price list.
#[derive(Debug, Clone)]
pub struct Policy {
    items: Vec<Item>,
}

impl Policy {
    /// Builds a policy, rejecting any item the price list does not cover.
    pub fn new(items: &[Item]) -> Result<Self, UnknownItemType> {
        for item in items {
            if base_premium(&item.item_type).is_none() {
                return Err(UnknownItemType(item.item_type.clone()));
            }
        }
        Ok(Self {
            items: items.to_vec(),
        })
    }

    /// The items this policy covers.
    pub fn items(&self) -> &[Item] {
        &self.items
    }

    /// Sum of the item base premiums, with alike components grouped so the
    /// building-block rate can apply.
    pub fn base_premium(&self) -> Amount {
        let mut total = Amount::zero();
        let mut component_counts: BTreeMap<&str, u64> = BTreeMap::new();

        for item in &self.items {
            if is_component(&item.item_type) {
                *component_counts.entry(&item.item_type).or_insert(0) += 1;
            } else {
                total = total + self.item_base_premium(item);
            }
        }

        for count in component_counts.values() {
            total = total + Amount::whole(i128::from(component_group_premium(*count)));
        }
        total
    }

    /// Base premium of one non-component item.
    fn item_base_premium(&self, item: &Item) -> Amount {
        let g = base_premium(&item.item_type).expect("validated on construction");
        Amount::whole(i128::from(g))
    }

    /// Sum of the items' unmodified insurance values; the basis for the cap.
    pub fn insurance_sum(&self) -> i128 {
        self.items
            .iter()
            .map(|item| {
                i128::from(insurance_value(&item.item_type).expect("validated on construction"))
            })
            .sum()
    }
}
